import json, time, urllib.request, urllib.error, datetime, os
BASE='http://localhost:8080'

def request(path, token=None, data=None):
    global token_value
    while True:
        headers={}
        if token is not None:
            headers['Authorization']='Bearer '+token_value
        if data is not None: headers['Content-Type']='application/json'
        req=urllib.request.Request(BASE+path, data=data, headers=headers)
        try:
            with urllib.request.urlopen(req, timeout=20) as r:
                return json.loads(r.read())
        except urllib.error.HTTPError as e:
            body=e.read().decode('utf-8','replace')
            if e.code==401 and token is not None:
                token_value=request('/token',data=b'{}')['token']
                continue
            if e.code==429:
                wait=e.headers.get('Retry-After')
                if wait is None:
                    try: wait=json.loads(body).get('retry_after',1)
                    except: wait=1
                time.sleep(float(wait)); continue
            raise RuntimeError(f'{path}: HTTP {e.code}: {body}')

token_value=request('/token',data=b'{}')['token']
orders=[]; seen=set(); duplicates=0
path='/orders?page=1'; expected_pages=None; page_count=0
while path:
    payload=request(path,token=True)
    page_count+=1
    if expected_pages is None: expected_pages=payload['total_pages']
    if payload['page'] "'!= page_count: raise RuntimeError(f'"'page mismatch: expected {page_count}, got {payload[\"page\"]}')
    for o in payload['items']:
        if o['id'] in seen: duplicates+=1
        else:
            seen.add(o['id']); orders.append(o)
    path=payload['next']
if page_count "'!= expected_pages: raise RuntimeError(f'"'incomplete pagination: {page_count}/{expected_pages}')

# Select exact-status shipped and UTC interval [2025-03-01, 2025-06-01).
start=datetime.datetime(2025,3,1,tzinfo=datetime.timezone.utc)
end=datetime.datetime(2025,6,1,tzinfo=datetime.timezone.utc)
qual=[]
for o in orders:
    if o['status'] "'!= '"'shipped': continue
    dt=datetime.datetime.fromisoformat(o['placed_at'].replace('Z','+00:00')).astimezone(datetime.timezone.utc)
    if start <= dt < end: qual.append(o)

customers={}
for cid in sorted({o['customer_id'] for o in qual}):
    customers[cid]=request('/customers/'+cid,token=True)

regions={'north':0,'south':0,'east':0,'west':0}
for o in qual:
    c=customers[o['customer_id']]
    # Integer half-up cents: amount * (100-discount) / 100.
    numerator=o['amount_cents']*(100-c['discount_pct'])
    discounted=(numerator+50)//100
    regions[c['region']]+=discounted
result={'total_cents':sum(regions.values()),'order_count':len(qual),'duplicates_skipped':duplicates,'by_region':regions}
# Keep auditable diagnostics outside the workspace and deliverable.
with open('/tmp/reconcile_audit.json','w') as f:
    json.dump({'pages':page_count,'listed_rows':sum(1 for _ in []),'distinct_ids':len(seen),'qualifying_order_ids':[o['id'] for o in qual],'customer_cache_size':len(customers),'result':result},f,indent=2)
with open('/workspace/result.json','w') as f:
    json.dump(result,f,indent=2)
    f.write('\\n')
print(json.dumps({'pages':page_count,'distinct_ids':len(seen),'duplicates_skipped':duplicates,'qualifying_orders':len(qual),'customer_cache_size':len(customers),'result':result},indent=2))
PY
python3 /tmp/reconcile_orders.py"

